// Replays the shared vectors (test/vectors.ts: the committed file, or the seeded random set PROPAMM_VECTORS names),
// which LadderMathVectors.t.sol, integration/VenueVectors.t.sol and the Rust SDK's tests/vectors.rs replay too, all generated by the
// independent BigInt model in contracts/test/vectors/ladder-reference.mjs.
import {
  type Address,
  encodeAbiParameters,
  encodeEventTopics,
  getAbiItem,
  getAddress,
  type Hex,
  type Log,
  toFunctionSelector,
  zeroAddress,
} from 'viem'
import { assert, describe, expect, test } from 'vitest'
import {
  Abis,
  type Actions,
  Errors,
  HotWord,
  Ladder,
  Post,
  PostOutcome,
  Price,
  Quote,
  Shape,
  type Snapshot,
  Venue,
} from '../src/index.js'
import {
  committed,
  data,
  direction,
  ladder,
  postCall,
  type QuoteCase,
  referenceArgs,
  refusal,
  type Vector,
} from './vectors.js'

const VENUE = '0x1111111111111111111111111111111111111111'
const OTHER = '0x2222222222222222222222222222222222222222'

function price(v: Vector): Ladder.FillResult {
  const hot = HotWord.decode(v.hot)
  return Ladder.fill(
    Ladder.curve(hot, BigInt(v.sizeUnit), v.baseIn),
    BigInt(v.w0),
    BigInt(v.w1),
    v.exactIn,
    BigInt(v.amount),
    BigInt(v.consumed),
  )
}

describe('ladder vectors', () => {
  test.skipIf(!committed)('has every section', () => {
    expect(data.vectors.length >= 2000, 'vector count').toBeTruthy()
    expect(data.splits.length >= 40, 'split count').toBeTruthy()
    expect(data.shapeChecks.length >= 100, 'shape check count').toBeTruthy()
    const kinds = new Set(data.vectors.map((v) => v.expect))
    expect([...kinds].sort()).toStrictEqual([
      'InsufficientDepth',
      'ZeroFill',
      'ok',
    ])
    expect(
      data.vectors.some((v) => v.consumed !== '0'),
      'consumed offsets covered',
    ).toBeTruthy()
    expect(
      data.hotWords.length >= 50 &&
        data.prices.length >= 40 &&
        data.shapes.length >= 20 &&
        data.shapeRejects.length >= 5,
    ).toBeTruthy()
    expect(
      data.posts.length >= 15 &&
        data.quotes.length >= 10 &&
        data.outcomes.length >= 10,
    ).toBeTruthy()
  })

  test('decodes and re-encodes every hot word', () => {
    for (const v of data.vectors) {
      const hot = HotWord.decode(v.hot)
      expect(hot.mid.toString(), v.name).toBe(v.mid)
      expect(hot.widthScale.toString(), v.name).toBe(v.widthScale)
      expect(hot.depthScale.toString(), v.name).toBe(v.depthScale)
      expect((v.baseIn ? hot.bidWiden : hot.askWiden).toString(), v.name).toBe(
        v.widen,
      )
      expect(direction(v.baseIn, v.exactIn), v.name).toBe(v.direction)
      const { sides, ...fields } = hot
      expect(
        HotWord.fromFields({ ...fields, flags: HotWord.sidesFlags(sides) }),
        v.name,
      ).toBe(v.hot)
      if (hot.mid !== 0n && hot.sequence > 1) {
        const { word } = Post.order({ ...fields, pairIndex: 0, sides })
        expect(word, v.name).toBe(v.hot)
      }
    }
  })

  test('prices every vector exactly', () => {
    for (const v of data.vectors) {
      const r = price(v)
      if (v.expect === 'ok') {
        assert(r.ok, `${v.name}: expected ok, got ${r.ok ? '' : r.error}`)
        expect(r.amountIn.toString(), `${v.name}: amountIn`).toBe(v.amountIn)
        expect(r.amountOut.toString(), `${v.name}: amountOut`).toBe(v.amountOut)
        expect(r.baseFilled.toString(), `${v.name}: baseFilled`).toBe(
          v.baseFilled,
        )
      } else {
        expect(r, v.name).toStrictEqual({ ok: false, error: v.expect })
      }
    }
  })

  test('chains every split through consumed and never beats the whole', () => {
    let dust = 0
    for (const sp of data.splits) {
      const whole = data.vectors[sp.whole] as Vector
      expect(whole.expect, sp.name).toBe('ok')
      const w = price(whole)
      assert(w.ok, sp.name)
      let consumed = BigInt(whole.consumed)
      let traded = 0n
      let paid = 0n
      let received = 0n
      for (const index of sp.parts) {
        const part = data.vectors[index] as Vector
        expect(
          BigInt(part.consumed),
          `${sp.name}: part starts where the last stopped`,
        ).toBe(consumed)
        expect(part.hot, sp.name).toBe(whole.hot)
        expect(part.direction, sp.name).toBe(whole.direction)
        const r = price(part)
        if (!r.ok) {
          dust++
          continue
        }
        consumed += r.baseFilled
        traded += BigInt(part.amount)
        paid += r.amountIn
        received += r.amountOut
      }
      expect(traded, sp.name).toBe(BigInt(whole.amount))
      if (whole.exactIn)
        expect(
          received <= w.amountOut,
          `${sp.name}: split paid out more`,
        ).toBeTruthy()
      else
        expect(paid >= w.amountIn, `${sp.name}: split cost less`).toBeTruthy()
    }
    if (committed) expect(dust > 0, 'dust parts covered').toBeTruthy()
  })

  test('returns the exact ShapeWord.check reason for every shape check', () => {
    for (const c of data.shapeChecks) {
      const words = c.words.map((w) => BigInt(w))
      expect(Shape.check(words), c.name).toBe(c.reason)
      if (c.reason === 0) {
        const shape = Shape.fromWords(words)
        expect(Shape.from(shape).words, c.name).toStrictEqual(shape.words)
      } else {
        expect(() => Shape.fromWords(words), c.name).toThrow(
          expect.objectContaining({
            name: 'InvalidShapeError',
            reason: c.reason,
          }),
        )
      }
    }
  })
})

describe('encoding vectors', () => {
  test('packs, unpacks and decodes every hot word as the reference does', () => {
    for (const h of data.hotWords) {
      const fields: HotWord.Fields = {
        mid: BigInt(h.mid),
        bidWiden: h.bidWiden,
        askWiden: h.askWiden,
        widthScale: h.widthScale,
        depthScale: h.depthScale,
        shapeId: h.shapeId,
        validUntil: h.validUntil,
        sequence: h.seq,
        flags: h.flags,
      }
      expect(HotWord.fromFields(fields), h.name).toBe(h.word)
      expect(HotWord.toFields(h.word), h.name).toStrictEqual(fields)
      expect(HotWord.isWellFormed(h.word), `${h.name}: isWellFormed`).toBe(
        h.wellFormed,
      )
      expect(HotWord.withoutRefill(h.word), `${h.name}: withoutRefill`).toBe(
        h.stored,
      )
      const { flags, ...rest } = fields
      // A stored word carries only the off flags; a post entry may carry refill bits, never reserved ones.
      if (flags <= 3) {
        const hot = HotWord.decode(h.word)
        expect(hot, h.name).toStrictEqual({ ...rest, sides: hot.sides })
        expect(HotWord.sidesFlags(hot.sides), h.name).toBe(flags)
        expect(HotWord.sideOff(hot, true), h.name).toBe((flags & 1) !== 0)
        expect(HotWord.sideOff(hot, false), h.name).toBe((flags & 2) !== 0)
      } else {
        expect(() => HotWord.decode(h.word), h.name).toThrow(
          Errors.InvalidHotWordError,
        )
      }
      if (flags <= 15) {
        const entry = HotWord.decodeEntry(h.word)
        expect(
          HotWord.sidesFlags(entry.sides) | HotWord.refillFlags(entry.refill),
          h.name,
        ).toBe(flags)
        if (h.wellFormed && h.seq > 1) {
          const { word } = Post.order({
            ...rest,
            pairIndex: 0,
            sides: entry.sides,
            refill: entry.refill,
          })
          expect(word, `${h.name}: Post.order`).toBe(h.word)
        }
      } else {
        expect(() => HotWord.decodeEntry(h.word), h.name).toThrow(
          Errors.InvalidHotWordError,
        )
      }
    }
  })

  test('parses and prints every price as the reference does', () => {
    for (const p of data.prices) {
      if (p.ok) {
        expect(Price.parse(p.text), JSON.stringify(p.text)).toBe(BigInt(p.mid))
        expect(Price.format(BigInt(p.mid)), JSON.stringify(p.text)).toBe(
          p.canonical,
        )
      } else {
        expect(() => Price.parse(p.text), JSON.stringify(p.text)).toThrow(
          Errors.InvalidPriceError,
        )
      }
    }
  })

  test('encodes every shape as the reference does, and refuses what it refuses', () => {
    for (const s of data.shapes) {
      const shape = Shape.from({
        bids: ladder(s.bidSizes, s.bidSpreads),
        asks: ladder(s.askSizes, s.askSpreads),
      })
      expect(shape.words, s.name).toStrictEqual(s.words.map((w) => BigInt(w)))
      const back = Shape.fromWords(shape.words)
      expect([back.bids, back.asks], s.name).toStrictEqual([
        shape.bids,
        shape.asks,
      ])
    }
    for (const s of data.shapeRejects) {
      expect(
        () =>
          Shape.from({
            bids: ladder(s.bidSizes, s.bidSpreads),
            asks: ladder(s.askSizes, s.askSpreads),
          }),
        `${s.name} (${s.error})`,
      ).toThrow(Errors.InvalidShapeError)
    }
  })

  test('builds every post batch as the reference does, or refuses it for the same reason', () => {
    expect(
      toFunctionSelector(getAbiItem({ abi: Abis.venueAbi, name: 'post' })),
    ).toBe(data.postSelector)
    let built = 0
    for (const v of data.posts) {
      let call: ReturnType<typeof Actions.maker.bulkOrders.call>
      try {
        call = postCall(VENUE, v)
      } catch (e) {
        expect(refusal(e), `${v.name}: ${(e as Error).message}`).toBe(v.expect)
        continue
      }
      expect(v.expect, `${v.name}: built a batch the reference refuses`).toBe(
        'ok',
      )
      expect(call.data, v.name).toBe(v.calldata)
      expect(call.args[0], v.name).toBe(v.packed)
      expect(call.posts, v.name).toStrictEqual(
        v.posts.map(([pairIndex, sequence], k) => ({
          pairIndex,
          sequence,
          word: v.stored[k],
        })),
      )
      const entries = Post.unpack(v.packed)
      expect(
        entries.map((e) => [e.pairIndex, HotWord.withoutRefill(e.word)]),
        v.name,
      ).toStrictEqual(v.posts.map(([pairIndex], k) => [pairIndex, v.stored[k]]))
      expect(
        entries.map((e) =>
          HotWord.refillFlags(HotWord.decodeEntry(e.word).refill),
        ),
        v.name,
      ).toStrictEqual(v.refills)
      built++
    }
    if (committed)
      expect(
        built >= 10 && built < data.posts.length,
        `${built} of ${data.posts.length}`,
      ).toBeTruthy()
  })

  test("reads every transaction's post outcomes as the reference does, from its Posted events alone", () => {
    const posted = (address: Address, [pairIndex, word]: [number, Hex]) =>
      ({
        address,
        topics: encodeEventTopics({
          abi: Abis.venueAbi,
          eventName: 'Posted',
          args: { pairIndex },
        }),
        data: encodeAbiParameters([{ type: 'bytes32' }], [word]),
      }) as unknown as Log
    for (const v of data.outcomes) {
      const calls = v.calls.map((c) => postCall(VENUE, c))
      // The venue's events, and each once more from another contract, which must not count.
      const logs = v.posted.flatMap((p) => [posted(OTHER, p), posted(VENUE, p)])
      const expected = v.outcomes.map(({ accepted, skipped }, i) => {
        const refs = (entries: [number, number][]) =>
          entries.map(([pairIndex, sequence]) =>
            (calls[i]?.posts ?? []).find(
              (p) => p.pairIndex === pairIndex && p.sequence === sequence,
            ),
          )
        return {
          accepted: refs(accepted),
          skipped: refs(skipped),
          allAccepted: skipped.length === 0,
        }
      })
      expect(PostOutcome.fromBatch(calls, logs), v.name).toStrictEqual(expected)
      if (calls.length === 1)
        expect(
          PostOutcome.fromLogs(calls[0] as (typeof calls)[0], logs),
          v.name,
        ).toStrictEqual(expected[0])
    }
  })
})

const BASE: Address = getAddress('0x000000000000000000000000000000000000ba5e')
const QUOTE: Address = getAddress('0x0000000000000000000000000000000000000c0e')

/** One case through the SDK's own model of a pair: `HotWord.decodeEntry` and `Ladder.applyRefill` for posts,
 * `Quote.local` for quotes, and its `consumedAfter` for fills. */
function replay(c: QuoteCase): number {
  const shapes = new Map<number, Shape.Words>()
  let stored: Hex = HotWord.initial
  let consumed: Ladder.Consumed = { bids: 0n, asks: 0n }
  let balances = { base: BigInt(c.inventory[0]), quote: BigInt(c.inventory[1]) }
  let fills = 0
  c.steps.forEach((s, j) => {
    const label = `${c.name}: step ${j} ${s.op}`
    if (s.op === 'setShape') {
      shapes.set(
        s.shapeId,
        Shape.fromWords(s.words.map((w) => BigInt(w))).words,
      )
    } else if (s.op === 'post') {
      expect(HotWord.isWellFormed(s.word), label).toBeTruthy()
      const entry = HotWord.decodeEntry(s.word)
      const accepted = entry.sequence > HotWord.decode(stored).sequence
      expect(accepted, `${label}: accepted`).toBe(s.accepted)
      if (accepted) {
        stored = HotWord.withoutRefill(s.word)
        consumed = Ladder.applyRefill(consumed, entry.refill)
      }
    } else {
      const hot = HotWord.decode(stored)
      const pair: Snapshot.PairState = {
        ok: true,
        pairIndex: 0,
        base: BASE,
        quote: QUOTE,
        sizeUnit: BigInt(c.sizeUnit),
        access: 'open',
        hook: zeroAddress,
        hookFlags: 0,
        hotWord: stored,
        hot,
        consumed,
        midBand: { minMid: 0n, maxMid: 0n },
        shapeWords: shapes.get(hot.shapeId) ?? [0n, 0n, 0n, 0n],
        shape: null,
        inventory: balances,
        hookLiquidity: { base: 0n, quote: 0n },
      }
      const source = {
        block: { timestamp: BigInt(c.timestamp) },
        state: { halted: false, maxTakerPriorityFee: Venue.noPriorityFeeCap },
        pairs: [pair],
      }
      const [tokenIn, tokenOut] = s.baseIn ? [BASE, QUOTE] : [QUOTE, BASE]
      const r = Quote.local(source, {
        pairIndex: 0,
        tokenIn,
        tokenOut,
        amount: BigInt(s.amount),
        exactIn: s.exactIn,
        priorityFee: 0n,
      })
      if (s.expect === 'ok') {
        assert(
          r.ok,
          `${label}: expected ok, got ${r.ok ? '' : `${r.error.errorName}(${r.error.args.join(', ')})`}`,
        )
        expect(r.amountIn.toString(), `${label}: amountIn`).toBe(s.amountIn)
        expect(r.amountOut.toString(), `${label}: amountOut`).toBe(s.amountOut)
        expect(r.baseFilled.toString(), `${label}: baseFilled`).toBe(
          s.baseFilled,
        )
        if (s.op === 'fill') {
          consumed = r.consumedAfter
          balances = s.baseIn
            ? {
                base: balances.base + r.amountIn,
                quote: balances.quote - r.amountOut,
              }
            : {
                base: balances.base - r.amountOut,
                quote: balances.quote + r.amountIn,
              }
          fills++
        }
      } else {
        assert(
          !r.ok,
          `${label}: expected ${s.expect}, quoted ${r.ok ? `${r.amountIn}/${r.amountOut}` : ''}`,
        )
        expect(r.error.errorName, label).toBe(s.expect)
        expect(
          referenceArgs(r.error.args, { base: BASE, quote: QUOTE }),
          `${label}: args`,
        ).toStrictEqual(s.args)
      }
    }
    expect(
      [consumed.bids.toString(), consumed.asks.toString()],
      `${label}: consumed`,
    ).toStrictEqual(s.consumed)
    expect(
      [balances.base.toString(), balances.quote.toString()],
      `${label}: inventory`,
    ).toStrictEqual(s.inventory)
  })
  return fills
}

describe('quote vectors', () => {
  test("follows every case's posts, quotes and fills with the SDK's own model of a pair", () => {
    let fills = 0
    for (const c of data.quotes) fills += replay(c)
    if (committed) expect(fills >= 40, `${fills} fills`).toBeTruthy()
  })
})
